"""Polynomial-time reduction from Independent Set to Vertex Cover.

Key fact: S is an independent set in G = (V, E) if and only if V \\ S is a
vertex cover of G.  Therefore G has an independent set of size >= k iff G
has a vertex cover of size <= n - k.  The reduction keeps the same graph
and maps the parameter k to n - k.
"""

from __future__ import annotations

from typing import Any


def reduce(instance: dict) -> dict:
    """Reduce an Independent Set instance to a Vertex Cover instance.

    Input : {"n": n, "edges": [[u, v], ...], "k": k}   (Independent Set)
    Output: {"n": n, "edges": [[u, v], ...], "k": n - k} (Vertex Cover)

    A set S is independent iff its complement V \\ S is a vertex cover, so
    the graph has an independent set of size >= k exactly when it has a
    vertex cover of size <= n - k.
    """
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    return {"n": n, "edges": [list(e) for e in edges], "k": n - k}
EOF
cat > solvers.py <<'EOF'
"""Brute-force solvers for Independent Set and Vertex Cover (small n)."""

from __future__ import annotations

from itertools import combinations


def is_independent_set(n, edges, chosen) -> bool:
    chosen = set(chosen)
    return all(not (u in chosen and v in chosen) for u, v in edges)


def is_vertex_cover(n, edges, chosen) -> bool:
    chosen = set(chosen)
    return all(u in chosen or v in chosen for u, v in edges)


def solve_independent_set(instance) -> bool:
    """True iff graph has an independent set of size >= k."""
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    for size in range(k, n + 1):
        for chosen in combinations(range(n), size):
            if is_independent_set(n, edges, chosen):
                return True
    return False


def solve_vertex_cover(instance) -> bool:
    """True iff graph has a vertex cover of size <= k."""
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    for size in range(0, k + 1):
        for chosen in combinations(range(n), size):
            if is_vertex_cover(n, edges, chosen):
                return True
    return False
EOF
